'use strict';

/**
 * The 59 preflight checks: the single source of truth for ids, titles, severities and
 * the prose in skills/preflight/references/checklist.md and the README table
 * (both generated by tools/gen-docs.js).
 *
 * mode:
 *   auto        the script decides pass/fail on its own
 *   auto+agent  the script flags candidates (warn); the agent verifies each one
 *   manual      the script gathers context; the agent or a human (dashboards) decides
 *
 * question: what the agent must answer for a warn/manual result. Check groups can
 * replace it with a more specific question for a given finding.
 */

