const BY_ID = new Map(CHECKS.map((c) => [c.id, c]));

function getCheck(id) {
  const meta = BY_ID.get(id);
  if (!meta) throw new Error(`Unknown check id: ${id}`);
  return meta;
}

module.exports = { GROUPS, CHECKS, getCheck };
